'use strict';
window.NoiraControls=(()=>{
 const auth=window.BarometrAuth,esc=auth.esc,$=s=>document.querySelector(s);
 const fmt=v=>new Intl.NumberFormat(window.NoiraI18n?.locale||'cs-CZ',{maximumFractionDigits:3}).format(v);
 const date=v=>new Date(v*1000).toLocaleString(window.NoiraI18n?.locale||'cs-CZ');
 const days=['Pondělí','Úterý','Středa','Čtvrtek','Pátek','Sobota','Neděle'];
 const types={inventory_outside_hours:'Inventura mimo otevírací dobu',repeated_shortage:'Opakované manko',large_writeoff:'Velký odpis',large_movement:'Velký pohyb',outside_hours:'Pohyb mimo otevírací dobu',repeated_writeoff:'Opakované odpisy',inventory_difference:'Rozdíl inventury',round_trip_transfer:'Rychlý přesun tam a zpět',repeated_correction:'Opakované opravy inventur'};
 function restock(rows,owner=false){
  if(!rows.length)return '';
  return '<section class="panel hub-panel restock-widget" aria-labelledby="restock-heading"><h2 id="restock-heading">Nutné doplnit skladové zásoby!</h2><p>Tyto produkty dosáhly nastaveného minima nebo klesly pod něj.</p><div class="tablewrap"><table><thead><tr>'+ (owner?'<th>Provoz</th>':'')+'<th>Produkt / sklad</th><th>Aktuálně</th><th>Minimum</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr>'+(owner?'<td translate="no">'+esc(r.venueName)+'</td>':'')+'<td><strong translate="no">'+esc(r.productName)+'</strong><small translate="no">'+esc(r.storeName)+'</small></td><td><strong class="stock-critical">'+fmt(r.quantity)+' '+esc(r.unit)+'</strong></td><td>'+fmt(r.minimum)+' '+esc(r.unit)+'</td><td>'+(owner?'<button data-enter-stock="'+esc(r.venueId)+'" data-source-route="#product/'+encodeURIComponent(r.productId)+'/'+encodeURIComponent(r.storeId)+'">Otevřít produkt</button>':'<a href="#product/'+encodeURIComponent(r.productId)+'/'+encodeURIComponent(r.storeId)+'">Otevřít produkt →</a>')+'</td></tr>').join('')+'</tbody></table></div></section>';
 }
 function owner(venues){setTimeout(()=>mountAttention(venues),0);return restock(venues.flatMap(v=>(v.lowStock||[]).map(r=>({...r,venueId:v.id,venueName:v.name}))),true)+'<section class="panel hub-panel" id="stock-attention"><h2>Neobvyklé pohyby a inventury</h2><p>Prověřujeme významné inventurní rozdíly, velké nebo opakované odpisy a opakované opravy stejné inventury. Běžný příjem zboží ani čas mimo otevírací dobu samy upozornění nevytvářejí. Jde o podnět ke kontrole, nikoli důkaz podvodu.</p><div data-attention-body>Načítání…</div></section>'}
 function settings(venues){return '<section class="panel hub-panel"><h2>Provozní doba a limity upozornění</h2>'+venues.map(v=>'<div class="controls-setting"><strong translate="no">'+esc(v.name)+'</strong><button data-controls-venue="'+esc(v.id)+'">Otevírací doba a upozornění</button></div>').join('')+'</section>'}
 async function mountAttention(venues){
  const root=$('#stock-attention [data-attention-body]');if(!root)return;
  root.innerHTML='<div class="attention-filters"><label>Provoz<select data-attention-venue><option value="">Všechny provozy</option>'+venues.map(v=>'<option value="'+esc(v.id)+'" translate="no">'+esc(v.name)+'</option>').join('')+'</select></label><label>Stav<select data-attention-status><option value="open">K prověření</option><option value="resolved">Vysvětlené</option><option value="all">Všechny</option></select></label></div><div data-attention-list></div>';
  let alerts=[],generation=0;
  const paint=()=>{const selected=root.querySelector('[data-attention-status]').value;root.querySelector('[data-attention-list]').innerHTML=alerts.filter(a=>selected==='all'||a.resolved===(selected==='resolved')).map(a=>'<details class="attention-case"><summary><strong>'+esc(types[a.type]||a.type)+'</strong> · <bdi translate="no">'+esc(a.venueName)+' · '+esc(a.productName||a.storeName)+'</bdi><small>'+esc(date(a.at))+' · '+(a.resolved?'Vysvětlené':'K prověření')+'</small></summary><p>'+esc(a.explanation)+'</p><p translate="no">'+esc(a.storeName)+' · '+esc(a.actorName)+'</p>'+(a.note?'<p class="attention-explanation"><strong>Poslední vyjádření:</strong> '+esc(a.note)+'<small translate="no">'+esc(a.resolvedBy)+' · '+esc(date(a.resolvedAt))+'</small></p>':'')+'<p><button data-enter-stock="'+esc(a.venueId)+'" data-source-route="'+esc(a.sourceRoute)+'">Otevřít související záznam</button></p><details><summary>Podklady a historie vysvětlení</summary><p translate="no">'+a.evidenceIds.map(esc).join(' · ')+'</p>'+a.history.map(h=>'<p><strong>'+ (h.resolved?'Vysvětleno':'Znovu otevřeno')+'</strong> · '+esc(date(h.created_at))+'<br><bdi translate="no">'+esc(h.actor_name)+'</bdi> · '+esc(h.note)+'</p>').join('')+'</details><form data-attention-case="'+esc(a.id)+'" data-venue="'+esc(a.venueId)+'" data-resolved="'+a.resolved+'"><label>'+(a.resolved?'Důvod znovuotevření':'Vysvětlení případu')+'<textarea name="note" minlength="5" maxlength="500" required></textarea></label><button class="primary" type="submit">'+(a.resolved?'Znovu otevřít':'Označit jako vysvětlené')+'</button><p class="form-error" role="alert"></p></form></details>').join('')||'<p>Pro zvolený filtr nejsou žádná upozornění.</p>';
   root.querySelectorAll('[data-attention-case]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await auth.send('/api/owner/venues/'+form.dataset.venue+'/attention/'+form.dataset.attentionCase,{note:form.elements.note.value,resolved:form.dataset.resolved!=='true'});await load()}catch(error){form.querySelector('.form-error').textContent=error.message;button.disabled=false}});
  };
  async function load(){const ticket=++generation;root.querySelector('[data-attention-list]').innerHTML='<p>Načítání…</p>';try{const data=await auth.api('/api/owner/attention?'+new URLSearchParams({venue:root.querySelector('[data-attention-venue]').value}));if(!root.isConnected||ticket!==generation)return;alerts=data.alerts;paint()}catch(error){if(root.isConnected)root.querySelector('[data-attention-list]').textContent=error.message}}
  root.querySelector('[data-attention-venue]').onchange=load;root.querySelector('[data-attention-status]').onchange=paint;await load();
 }
 async function editor(venue){
  const host=$('#modal');host.innerHTML='<div class="modal-backdrop"><section class="modal-content controls-modal" role="dialog" aria-modal="true" aria-labelledby="controls-title"><button class="modal-close" data-auth-close aria-label="Zavřít">×</button><h2 id="controls-title">Otevírací doba a upozornění</h2><div data-controls-body>Načítání…</div></section></div>';
  const target=host.querySelector('[data-controls-body]');
  try{const data=await auth.api('/api/owner/venues/'+venue+'/controls');if(!target.isConnected)return;
   const hours=data.openingHours,limits=data.limits;
   target.innerHTML='<form id="venue-controls-form"><label class="permission-line"><input name="hoursEnabled" type="checkbox" '+(hours.days?'checked':'')+'> Používat otevírací dobu</label><label>Časové pásmo<select name="timezone"><option value="Europe/Prague">Praha (Česko)</option><option value="Europe/Berlin">Berlín</option><option value="UTC">UTC</option></select></label><div class="opening-hours">'+days.map((name,i)=>{const row=hours.days?.[i]||{closed:true};return '<fieldset data-day="'+i+'"><legend>'+name+'</legend><label class="permission-line"><input type="checkbox" data-closed '+(row.closed?'checked':'')+'> Zavřeno</label><label>Od<input data-open type="time" value="'+esc(row.open||'10:00')+'" required></label><label>Do<input data-close type="time" value="'+esc(row.close||'22:00')+'" required></label></fieldset>'}).join('')+'</div><p class="hub-note">Zavření dříve než otevření znamená provoz přes půlnoc. Stejný čas znamená nepřetržitý provoz v daný den.</p><h3>Limity upozornění</h3><label>Rozdíl inventury (%)<input name="lossPercent" type="number" min="1" max="1000" value="'+limits.lossPercent+'" required></label><div class="two">'+Object.entries(limits.movementLimits).map(([unit,value])=>'<label>Významný rozdíl nebo odpis · '+esc(unit)+'<input data-limit-unit="'+esc(unit)+'" type="number" min="0.001" max="1000000000000" step="any" value="'+value+'" required></label>').join('')+'</div><label>Počet opakovaných odchylek<input name="repeatedCount" type="number" min="2" max="50" step="1" value="'+limits.repeatedCount+'" required></label><label>Rychlý zpětný přesun (minuty)<input name="transferMinutes" type="number" min="1" max="1440" value="'+limits.transferMinutes+'" required></label><label class="permission-line"><input name="outsideHours" type="checkbox" '+(limits.outsideHours?'checked':'')+'> Zohlednit čas u významných odchylek</label><p class="hub-note">Příjmy, vratky a běžné výdeje samy upozornění nevytvářejí. Odpisy se sčítají za sedm dní a musí dosáhnout množstevního limitu. Opravy se sledují u stejné inventury za třicet dní. Jednorázové vrácení přesunu se neoznačuje. U inventur se toleruje rozdíl do 1 kusu nebo 0,05 l/kg včetně; vyšší rozdíl musí překročit procentní nebo množstevní limit.</p><button class="primary" type="submit">Uložit nastavení provozu</button><p class="form-error" role="alert"></p></form>';
   const form=target.querySelector('form');form.elements.timezone.value=hours.timezone||'Europe/Prague';if(!form.elements.timezone.value){const option=document.createElement('option');option.value=hours.timezone;option.textContent=hours.timezone;form.elements.timezone.append(option);form.elements.timezone.value=hours.timezone}
   function update(){const enabled=form.elements.hoursEnabled.checked;form.elements.timezone.disabled=!enabled;form.querySelectorAll('[data-day]').forEach(day=>{day.querySelector('[data-closed]').disabled=!enabled;for(const input of day.querySelectorAll('[data-open],[data-close]'))input.disabled=!enabled||day.querySelector('[data-closed]').checked})}
   form.addEventListener('change',update);update();
   form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{
    const openingHours=form.elements.hoursEnabled.checked?{timezone:form.elements.timezone.value,days:Object.fromEntries([...form.querySelectorAll('[data-day]')].map(day=>[day.dataset.day,{closed:day.querySelector('[data-closed]').checked,open:day.querySelector('[data-open]').value,close:day.querySelector('[data-close]').value}]))}:{};
    await auth.send('/api/owner/venues/'+venue+'/controls',{openingHours,limits:{lossPercent:Number(form.elements.lossPercent.value),movementLimits:Object.fromEntries([...form.querySelectorAll('[data-limit-unit]')].map(input=>[input.dataset.limitUnit,Number(input.value)])),repeatedCount:Number(form.elements.repeatedCount.value),transferMinutes:Number(form.elements.transferMinutes.value),outsideHours:form.elements.outsideHours.checked}},'PUT');host.innerHTML='';window.dispatchEvent(new Event('hashchange'));
   }catch(error){form.querySelector('.form-error').textContent=error.message;button.disabled=false}};
  }catch(error){if(target.isConnected)target.textContent=error.message}
 }
 document.addEventListener('click',async event=>{const button=event.target.closest('[data-controls-venue],[data-enter-stock]');if(!button)return;
  if(button.dataset.controlsVenue)return editor(button.dataset.controlsVenue);
  button.disabled=true;try{const response=await auth.send('/api/owner/venues/'+button.dataset.enterStock+'/enter');location.assign(response.url+(button.dataset.sourceRoute||''))}catch(error){button.disabled=false;const message=document.createElement('p');message.setAttribute('role','alert');message.textContent=error.message;button.after(message)}
 });
 return {restock,owner,settings};
})();
